INSERT INTO agent_artifact (
    artifact_id, session_id, run_id, artifact_type, title, summary, content_ref,
    version, last_mentioned_at, created_at, updated_at
) VALUES (
    #{artifactId}, #{sessionId}, #{runId}, #{artifactType}, #{title}, #{summary}, #{contentRef},
    #{version}, #{lastMentionedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT id, artifact_id, session_id, run_id, artifact_type, title, summary, content_ref, version, last_mentioned_at, created_at, updated_at FROM agent_artifact WHERE session_id = #{sessionId}
AND ( title LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%') OR artifact_type LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY COALESCE(last_mentioned_at, updated_at, created_at) DESC LIMIT #{limit}
